function setEpochNow(){const e=Math.floor(Date.now()/1e3);document.getElementById("epochInput").value=e,convertEpoch()}function convertEpoch(){const e=document.getElementById("epochInput").value.trim();if(!e)return document.getElementById("utcOutput").value="",void(document.getElementById("localOutput").value="");let t=parseInt(e,10);if(isNaN(t))return document.getElementById("utcOutput").value="Invalid timestamp",void(document.getElementById("localOutput").value="Invalid timestamp");e.length<=11&&(t*=1e3);const n=new Date(t);if(isNaN(n.getTime()))return document.getElementById("utcOutput").value="Invalid Date",void(document.getElementById("localOutput").value="Invalid Date");document.getElementById("utcOutput").value=n.toUTCString(),document.getElementById("localOutput").value=n.toString()}function convertDateToEpoch(){const e=document.getElementById("datetimePicker");if(!e.value)return document.getElementById("epochSecOutput").value="",void(document.getElementById("epochMsOutput").value="");const t=new Date(e.value).getTime(),n=Math.floor(t/1e3);document.getElementById("epochSecOutput").value=n,document.getElementById("epochMsOutput").value=t}function setPickerToNow(){const e=new Date,t=6e4*e.getTimezoneOffset(),n=new Date(e.getTime()-t).toISOString().slice(0,16);document.getElementById("datetimePicker").value=n,convertDateToEpoch()}function copyResult(e,t){const n=document.getElementById(e);n&&n.value&&(n.select(),navigator.clipboard.writeText(n.value),flashCopied(t))}window.addEventListener("load",function(){setPickerToNow(),setEpochNow()});